PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS services (
 id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', service_date TEXT NOT NULL DEFAULT '', venue TEXT NOT NULL DEFAULT '', pdf_name TEXT NOT NULL DEFAULT '', closed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS scenarios (
 id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS teams (
 id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, scenario_id TEXT REFERENCES scenarios(id) ON DELETE SET NULL, name TEXT NOT NULL, color_name TEXT NOT NULL DEFAULT '', color_hex TEXT NOT NULL DEFAULT '', no_vest INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS workers (
 id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, service_date TEXT NOT NULL DEFAULT '', block_id TEXT NOT NULL DEFAULT '', block_label TEXT NOT NULL DEFAULT '', trabajo TEXT NOT NULL DEFAULT '', is_reserve INTEGER NOT NULL DEFAULT 0, personal TEXT NOT NULL, especialidad TEXT NOT NULL DEFAULT '', h_llam TEXT NOT NULL DEFAULT '', inicio TEXT NOT NULL DEFAULT '', fin TEXT NOT NULL DEFAULT '', pausa TEXT NOT NULL DEFAULT '', n_dieta INTEGER NOT NULL DEFAULT 0, is_coordinator INTEGER NOT NULL DEFAULT 0, actual_inicio TEXT NOT NULL DEFAULT '', actual_fin TEXT NOT NULL DEFAULT '', actual_pausa TEXT NOT NULL DEFAULT '', actual_n_dieta INTEGER, movil TEXT NOT NULL DEFAULT '', scenario_id TEXT REFERENCES scenarios(id) ON DELETE SET NULL, team_id TEXT REFERENCES teams(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT '', arrival_at TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', rating_uniformidad INTEGER, rating_actitud INTEGER, rating_puntualidad INTEGER, included INTEGER NOT NULL DEFAULT 1, page INTEGER NOT NULL DEFAULT 0, pdf_row INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS incidents (
 id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, worker_id TEXT REFERENCES workers(id) ON DELETE SET NULL, personal TEXT NOT NULL DEFAULT '', service_date TEXT NOT NULL DEFAULT '', trabajo TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', severity TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', action_taken TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS requirements (
 id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE, service_date TEXT NOT NULL DEFAULT '', trabajo TEXT NOT NULL DEFAULT '', team_id TEXT REFERENCES teams(id) ON DELETE CASCADE, required_count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS audit (
 id TEXT PRIMARY KEY, service_id TEXT REFERENCES services(id) ON DELETE SET NULL, worker_id TEXT REFERENCES workers(id) ON DELETE SET NULL, actor TEXT NOT NULL DEFAULT '', event_type TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_workers_service ON workers(service_id, sort_order);
CREATE INDEX IF NOT EXISTS idx_incidents_service ON incidents(service_id);
CREATE INDEX IF NOT EXISTS idx_teams_service ON teams(service_id);
CREATE INDEX IF NOT EXISTS idx_requirements_service ON requirements(service_id);
